<section class="hero-card p-4 p-md-5">
  <div class="mb-4"><span class="badge text-bg-success-subtle mb-2">Consultas y exportación</span><h1 class="h2 fw-bold mb-1">Reportes</h1><p class="text-secondary mb-0">Filtra tus movimientos y descarga el resultado en CSV.</p></div>
  <?php if ($errors): ?><div class="alert alert-danger"><ul class="mb-0"><?php foreach ($errors as $message): ?><li><?= htmlspecialchars($message, ENT_QUOTES, 'UTF-8') ?></li><?php endforeach; ?></ul></div><?php endif; ?>
