    <div class="col-sm-6 col-lg-2"><label class="form-label" for="hasta">Fecha final</label><input class="form-control" type="date" id="hasta" name="hasta" value="<?= htmlspecialchars($filters['hasta'], ENT_QUOTES, 'UTF-8') ?>"></div>
