    <div class="col-sm-6 col-lg-3"><label class="form-label" for="categoria_id">Categoría</label><select class="form-select" id="categoria_id" name="categoria_id"><option value="">Todas</option><?php foreach ($categories as $category): ?><option value="<?= (int) $category['id'] ?>" <?= $filters['categoria_id'] === (string) $category['id'] ? 'selected' : '' ?>><?= htmlspecialchars($category['nombre'], ENT_QUOTES, 'UTF-8') ?> (<?= htmlspecialchars($category['tipo'], ENT_QUOTES, 'UTF-8') ?>)</option><?php endforeach; ?></select></div>
    <div class="col-sm-8 col-lg-2"><label class="form-label" for="descripcion">Descripción</label><input class="form-control" id="descripcion" name="descripcion" maxlength="255" value="<?= htmlspecialchars($filters['descripcion'], ENT_QUOTES, 'UTF-8') ?>"></div>
    <div class="col-sm-4 col-lg-1 d-grid"><button class="btn btn-outline-success" type="submit">Filtrar</button></div>
    <div class="col-12 d-flex gap-2"><a class="btn btn-outline-secondary" href="/reportes">Limpiar</a><a class="btn btn-success" href="/reportes/exportar?<?= htmlspecialchars(http_build_query($filters), ENT_QUOTES, 'UTF-8') ?>">Descargar CSV</a></div>
