  <div class="row g-3 mb-4"><div class="col-6 col-xl-3"><article class="feature-card"><p class="small text-secondary mb-1">Total ingresos</p><p class="h4 fw-bold text-success mb-0">$<?= number_format($summary['ingresos'], 2, ',', '.') ?></p></article></div><div class="col-6 col-xl-3"><article class="feature-card"><p class="small text-secondary mb-1">Total gastos</p><p class="h4 fw-bold text-danger mb-0">$<?= number_format($summary['gastos'], 2, ',', '.') ?></p></article></div><div class="col-6 col-xl-3"><article class="feature-card"><p class="small text-secondary mb-1">Balance del período</p><p class="h4 fw-bold mb-0 <?= $summary['saldo'] >= 0 ? 'text-success' : 'text-danger' ?>">$<?= number_format($summary['saldo'], 2, ',', '.') ?></p></article></div><div class="col-6 col-xl-3"><article class="feature-card"><p class="small text-secondary mb-1">Movimientos</p><p class="h4 fw-bold mb-0"><?= number_format($summary['cantidad'], 0, ',', '.') ?></p></article></div></div>
  <?php if (!$movements): ?><div class="text-center py-5"><h2 class="h5">No hay resultados</h2><p class="text-secondary mb-0">No encontramos movimientos con esos filtros.</p></div><?php else: ?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Fecha</th><th>Tipo</th><th>Categoría</th><th>Descripción</th><th class="text-end">Valor</th></tr></thead><tbody><?php foreach ($movements as $item): ?><tr><td><?= htmlspecialchars(date('d/m/Y', strtotime($item['fecha'])), ENT_QUOTES, 'UTF-8') ?></td><td><span class="badge <?= $item['tipo'] === 'ingreso' ? 'text-bg-success' : 'text-bg-warning' ?>"><?= $item['tipo'] === 'ingreso' ? 'Ingreso' : 'Gasto' ?></span></td><td><?= htmlspecialchars($item['categoria'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($item['descripcion'] ?? '—', ENT_QUOTES, 'UTF-8') ?></td><td class="text-end fw-semibold">$<?= number_format((float) $item['monto'], 2, ',', '.') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
